def classify_sentiment(text: str) -> Literal["POSITIVE", "NEGATIVE"]:
    """Classify sentiment of given text as either POSITIVE or NEGATIVE."""

    # Define a list of positive and negative words to use in the classification process.
    pos_words = ["good", "great", "awesome"]
    neg_words = ["bad", "terrible", "awful"]

    # Split input text into individual words.
    words = text.split()

    # Initialize counters for number of positive and negative words found in the text.
    num_pos, num_neg = 0, 0

    # Loop through each word in the list of words from the input text.
    for w in words:
        if w.lower() in pos_words:
            num_pos += 1
        elif w.lower() in neg_words:
            num_neg += 1

    # Determine sentiment based on number of positive and negative words found.    
    if num_pos > num_neg:
        return "POSITIVE"
    else:
        return "NEGATIVE"

